import { basename } from 'node:path';
import { DEFAULT_PROGRAM_NAME } from './constants.mjs';

function renderUsageLine(programName) {
  return `usage: ${programName} [-h] --a A\n`;
}

function renderError(programName, message) {
  return `${renderUsageLine(programName)}${programName}: error: ${message}\n`;
}

function readInlineValue(token) {
  let value = '';

  for (let index = 4; index < token.length; index += 1) {
    value += token[index];
  }

  return value;
}

function hasInlineValue(token) {
  return token.length >= 4
    && token[0] === '-'
    && token[1] === '-'
    && token[2] === 'a'
    && token[3] === '=';
}

function canUseAsValue(token) {
  return token.length === 1 || token[0] !== '-';
}

export function getProgramName(argv = process.argv) {
  if (argv.length > 1 && argv[1]) {
    return basename(argv[1]);
  }

  return DEFAULT_PROGRAM_NAME;
}

export function renderHelp(programName) {
  return `usage: ${programName} [-h] --a A\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n`;
}

export function parseCommandLine(argv = process.argv) {
  const programName = getProgramName(argv);
  const extras = [];
  let value;

  for (let index = 2; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      return {
        kind: 'help',
        programName,
        text: renderHelp(programName),
      };
    }

    if (token === '--a') {
      const nextIndex = index + 1;

      if (nextIndex >= argv.length || !canUseAsValue(argv[nextIndex])) {
        return {
          kind: 'error',
          exitCode: 2,
          programName,
          text: renderError(programName, 'argument --a: expected one argument'),
        };
      }

      value = argv[nextIndex];
      index = nextIndex;
      continue;
    }

    if (hasInlineValue(token)) {
      value = readInlineValue(token);
      continue;
    }

    extras.push(token);
  }

  if (value === undefined) {
    return {
      kind: 'error',
      exitCode: 2,
      programName,
      text: renderError(programName, 'the following arguments are required: --a'),
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      exitCode: 2,
      programName,
      text: renderError(programName, `unrecognized arguments: ${extras.join(' ')}`),
    };
  }

  return {
    kind: 'run',
    programName,
    value,
  };
}

